/**
 * Removes duplicate values from an array while keeping the first occurrence of each unique value.
 * 
 * @param {array<T>} arr - The array to process. T must be comparable (e.g., number, string).
 * @returns {array} A new array with duplicates removed.
 */
function removeDuplicates(arr) {
  return [...new Set(arr)]; // Create a copy of the array and then transform into a Set
}

// Example usage:
const nums = [1, 2, 3, 'a', 4, 5];
console.log(removeDuplicates(nums)); // Output: [1, 2, 3, 4, 5]
